  render: () => {
    const allValues = [
      'all',
      'build-variants',
      'ubuntu2004',
      'rhel8',
      'windows',
      'distros',
      'small',
      'large',
    ];
    const [state, setState] = useState<string[]>(allValues);
    return <TreeSelect tData={treeData} state={state} onChange={setState} />;
  },
  play: async ({ canvas }) => {
    const allCheckbox = canvas.getByLabelText('All');
    await expect(allCheckbox).toBeChecked();
  },
};

