  decorators: [
    (Story) => (
      <MemoryRouter>
        <Global styles={[resetStyles, bodyStyles]} />
        <AuthProvider
          evergreenAppURL={EVERGREEN_APP_URL_CONSTANT}
          localAuthRoute="/login"
          remoteAuthURL="/auth"
          shouldUseLocalAuth
        >
          <ToastProvider>
            <Story />
          </ToastProvider>
        </AuthProvider>
      </MemoryRouter>
    ),
  ],
