 63→    <Tooltip
 64→      onClose={onClose}
 65→      open={open}
 66→      refEl={refEl}
 67→      setOpen={setOpen}
 68→      triggerEvent="click"
 69→      {...props}
 70→    >
 71→      <ContentWrapper ref={popoverRef}>
 72→        {children}
 73→        <ButtonWrapper>
 74→          <Button
 75→            as="button"
 76→            onClick={() => {
 77→              onClose();
 78→              setOpen(false);
 79→            }}
 80→            size="small"
 81→          >
 82→            Cancel
 83→          </Button>
 84→          <Button
 85→            as="button"
